window.AUTH=window.AUTH||{};window.AUTH["22-105"]={"d":"22-105","id":"2022/22-105","n":"Coinbase v. Bielski","briefs":[{"k":"petitioner","label":"Brief of petitioner Coinbase, Inc.","date":"2023-01-20","url":"https://www.supremecourt.gov/DocketPDF/22/22-105/252832/20230120143746991_Coinbase%20Merits%20Brief%201-20-23%20Final.pdf","side":"pet","n":115},{"k":"respondent","label":"Brief of respondent Abraham Bielski","date":"2023-02-21","url":"https://www.supremecourt.gov/DocketPDF/22/22-105/255161/20230221122108808_22-105%20bs.pdf","side":"res","n":106},{"k":"respondent","label":"Brief of respondents David Suski, et al.","date":"2023-02-21","url":"https://www.supremecourt.gov/DocketPDF/22/22-105/255228/20230221163956457_Suski%20Merits%20Brief%20E%20FILE%20Feb%2021%2023.pdf","side":"res","n":57},{"k":"reply","label":"Reply of petitioner Coinbase, Inc.","date":"2023-03-09","url":"https://www.supremecourt.gov/DocketPDF/22/22-105/256623/20230309124431317_Coinbase%20Merits%20Reply%203-9-23%20Final.pdf","side":"pet","n":56}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r48_986b.pdf","tr":true,"items":[{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"sum":"Petitioners and others were charged in a single-count indictment with conspiracy and an attempt to obstruct interstate commerce by means of extortion, in violation of the Hobbs Act. Petitioners challenged the indictment as duplicitous, contending that its single count improperly charged both a conspiracy and an attempt to violate the Hobbs Act. The District Court refused to dismiss the indictment but required the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39, 50","1":"34"}},{"t":"case","label":"Allied-Bruce Terminix Cos. v. Dobson","cite":"513 U.S. 265","y":1995,"id":"1994/93-1001","sc":1,"sum":"The Court held that the Federal Arbitration Act applied to all disputes involving commerce, and thus the arbitration clause was valid and enforceable.","sumSrc":"Oyez","by":{"0":"32","2":"49","3":"23, 24"}},{"t":"case","label":"Apostol v. Gallion","cite":"870 F.2d 1335","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/870/1335/","op":2,"by":{"0":"39, 51","1":"21, 35","2":"42","3":"9"}},{"t":"case","label":"Arciniaga v. Gen. Motors Corp.","cite":"460 F.3d 231","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/460/231/","by":{"0":"48"}},{"t":"case","label":"Arthur Andersen LLP v. Carlisle","cite":"556 U.S. 624","y":2009,"id":"2008/08-146","sc":1,"op":5,"ar":1,"sum":"The Court found that regardless of whether the petitioner is eligible for a stay, a federal court of appeals has jurisdiction over a motion to stay under Section 16(a)(1) of the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"7, 30, 50","2":"39, 40"}},{"t":"case","label":"AT&T Mobility LLC v. Concepcion","cite":"563 U.S. 333","y":2011,"id":"2010/09-893","sc":1,"sum":"The Court held the Federal Arbitration Act preempts state laws that \"stand as obstacles to the FAA's objectives.\"","sumSrc":"Oyez","by":{"0":"29, 33","1":"10","2":"40","3":"10, 13"}},{"t":"case","label":"BancPass, Inc. v. Highway Toll Admin., L.L.C.","cite":"863 F.3d 391","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/391/","by":{"0":"51"}},{"t":"case","label":"Behrens v. Pelletier","cite":"516 U.S. 299","y":1996,"id":"1995/94-1244","sc":1,"sum":"The Court held that the court of appeals was not deprived of jurisdiction. The Court reasoned that the agent was not limited in such circumstances to one interlocutory appeal from a denial of qualified immunity.","sumSrc":"Oyez","by":{"0":"50-52"}},{"t":"case","label":"Berk v. Coinbase, Inc.","cite":"840 F. App’x 914","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/840/914/","by":{"0":"47"}},{"t":"case","label":"Blinco v. Green Tree Servicing, LLC","cite":"366 F.3d 1249","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/366/1249/","op":1,"by":{"0":"22","1":"38","3":"7"}},{"t":"case","label":"Bradford-Scott Data Corp. v. Physician Comput. Network, Inc.","cite":"128 F.3d 504","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/128/504/","op":4,"ar":2,"sum":"Rejecting the Ninth Circuit’s interpretation of Moses H. Cone.","sumSrc":"brief:0","by":{"0":"21-23, 31, 32, 44","1":"38","2":"2, 3, 15, 29, 30-33, 38, 41","3":"2, 3, 23"}},{"t":"case","label":"Britton v. Co-op Banking Grp.","cite":"916 F.2d 1405","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/916/1405/","op":2,"by":{"0":"13, 43, 45, 46, 49","2":"12"}},{"t":"case","label":"Buffler v. Elec. Comput. Programming Inst., Inc.","cite":"466 F.2d 694","y":1972,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/466/694/","by":{"0":"32"}},{"t":"case","label":"Bullard v. Blue Hills Bank","cite":"575 U.S. 496","y":2015,"id":"2014/14-116","sc":1,"sum":"The Court held that a bankruptcy court’s order denying confirmation of a repayment plan is not a final order for the purpose of immediate appeal.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Chuman v. Wright","cite":"960 F.2d 104","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/960/104/","op":1,"by":{"0":"51"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"20"}},{"t":"case","label":"Cox v. Ocean View Hotel Corp.","cite":"533 F.3d 1114","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/533/1114/","by":{"0":"48"}},{"t":"case","label":"Dekker v. Vivint Solar, Inc.","cite":"2021 WL 4958856","y":2021,"court":"9th Cir. Oct. 26","by":{"0":"47"}},{"t":"case","label":"Di Bella v. United States","cite":"369 U.S. 121","y":1962,"id":"1961/21","sc":1,"sum":"An order of a Federal District Court granting or denying a pre-indictment motion under Federal Rule of Criminal Procedure 41 (e) to suppress the evidentiary use in a federal criminal trial of property allegedly procured through an unlawful search and seizure is not appealable-even when rendered in a different district from that of trial. Pp. 121-133. 284 F. 2d 897, judgment vacated with instructions to dismiss the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Digital Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"op":1,"sum":"The Supreme Court ruled that the denial of immunity - while cause for concern - does not automatically create a right to immediate appeal. It is important to have final judgments before appeals are made, Justice David H. Souter wrote for the Court, and exceptions should only be made in particularly important cases.","sumSrc":"Oyez","by":{"0":"8, 42","1":"36-37","3":"11, 12"}},{"t":"case","label":"Doe v. Pub. Citizen","cite":"749 F.3d 246","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/749/246/","by":{"0":"21"}},{"t":"case","label":"Edelman v. Lynchburg Coll.","cite":"535 U.S. 106","y":2002,"id":"2001/00-1072","sc":1,"sum":"The Court held that the EEOC's relation-back regulation was an unassailable interpretation of Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Elgin v. Dep’t of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Fargo Women’s Health Org. v. Schafer","cite":"507 U.S. 1013","y":1993,"url":"https://supreme.justia.com/cases/federal/us/507/1013/","sc":1,"by":{"0":"47"}},{"t":"case","label":"Fernandez v. Bridgecrest Credit Co.","cite":"2022 WL 898593","y":2022,"court":"9th Cir. March 28","by":{"0":"47"}},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26","1":"17"}},{"t":"case","label":"Green Tree Fin. Corp.-Alabama v. Randolph","cite":"531 U.S. 79","y":2000,"id":"2000/99-1235","sc":1,"sum":"The Court held that an order compelling arbitration pursuant to the parties' agreement is a \"final decision with respect to an arbitration\" within the meaning of the Federal Arbitration Act making it immediately appealable pursuant to the FAA.","sumSrc":"Oyez","by":{"0":"6, 7"}},{"t":"case","label":"Griggs v. Provident Consumer Disc. Co.","cite":"459 U.S. 56","y":1982,"id":"1982/82-5082","sc":1,"op":39,"ar":37,"sum":"The Court of Appeals' analysis of Rule 4(a)(4) is contrary to the language and purposes of the 1979 amendments to the Rules of Appellate Procedure. Prior to 1979, if a notice of appeal was fied pending disposition of a motion to vacate, alter, or amend the judgment it was generally held that the district court retained jurisdiction to decide the motion and the notice of appeal was adequate for purposes of beginning …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 16, 20, 22, 25, 42, 46","1":"2, 9, 22, 27, 32, 35, 38","2":"28-32, 35, 37, 40-42","3":"1-6, 8-9, 11-17, 19, 22"}},{"t":"case","label":"Gulfstream Aerospace Corp. v. Mayacamas Corp.","cite":"485 U.S. 271","y":1988,"id":"1987/86-1329","sc":1,"sum":"Petitioner sued respondent in state court for breach of contract. Respondent did not remove the action to federal court, but, one month later, filed a diversity action against petitioner in the Federal District Court for breach of the same contract. The District Court denied petitioner's motion to stay or dismiss the action before it, finding that the facts of the case fell short of those necessary to justify the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Hall St. Assocs., L.L.C. v. Mattel, Inc.","cite":"552 U.S. 576","y":2008,"id":"2007/06-989","sc":1,"sum":"The Court affirmed the Ninth Circuit ruling and held that the provisions of the FAA are exclusive and cannot be expanded through contractual agreement. Writing for the majority, Justice David Souter pointed to words such as \"must\" and \"unless\" in the FAA as evidence that its provisions were intended to be mandatory and incapable of modification by the parties.","sumSrc":"Oyez","by":{"0":"5, 32, 49"}},{"t":"case","label":"Helstoski v. Meanor","cite":"442 U.S. 500","y":1979,"id":"1978/78-546","sc":1,"sum":"Mandamus was not the appropriate means of challenging the validity of the indictment on the ground that it violated the Speech or Debate Clause. Direct appeal to the Court of Appeals was available and was the proper course.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Helton v. Clements","cite":"787 F.2d 1016","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/787/1016/","by":{"0":"41"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Henry Schein, Inc. v. Archer & White Sales, Inc.","cite":"139 S. Ct. 524","y":2019,"id":"2018/17-1272","sc":1,"op":1,"ar":1,"sum":"The “wholly groundless” exception to the general rule that courts must enforce contracts that delegate threshold arbitrability questions to an arbitrator, not a court, is inconsistent with the Federal Arbitration Act and this Court’s precedent.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"8, 33, 48, 49, 51","1":"12","2":"40","3":"6, 8"}},{"t":"case","label":"Howsam v. Dean Witter Reynolds, Inc.","cite":"537 U.S. 79","y":2002,"id":"2002/01-800","sc":1,"sum":"The Court held that the applicability of the NASD time-limit rule is a matter presumptively for the arbitrator. Justice Breyer reasoned that the issue did not raise a substantive question of arbitrability requiring judicial resolution.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Int’l Ass’n of Machinists & Aerospace Workers, AFL-CIO v. Aloha Airlines, Inc.","cite":"776 F.2d 812","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/776/812/","by":{"0":"31"}},{"t":"case","label":"Knapke v. PeopleConnect, Inc.","cite":"38 F.4th 824","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/824/","by":{"0":"47"}},{"t":"case","label":"Levin v. Alms and Assocs., Inc.","cite":"634 F.3d 260","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/634/260/","op":1,"by":{"0":"22, 24","3":"21"}},{"t":"case","label":"Marrese v. Am. Acad. of Orthopaedic Surgeons","cite":"470 U.S. 373","y":1985,"id":"1984/83-1452","sc":1,"op":1,"sum":"After being denied membership in respondent American Academy of Orthopaedic Surgeons, petitioner orthopaedic surgeons each filed an action in an Illinois Circuit Court, alleging that the denial of membership violated their associational rights under Illinois common law. After the Illinois Appellate Court ultimately held that the complaint in one action failed to state a cause of action, the Circuit Court then …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"23"}},{"t":"case","label":"May v. Sheahan","cite":"226 F.3d 876","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/226/876/","by":{"0":"39, 40"}},{"t":"case","label":"McCullough v. Kammerer Corp.","cite":"331 U.S. 96","y":1947,"id":"scdb/1946-090","sc":1,"sum":"In a patent infringement suit, an appeal may be taken under § 129 of the Judicial Code, as amended, 28 U. S. C. § 227a, from an \"order\" denying on the merits a motion to set aside (because of unlawful use of the patent) an earlier decree which held the patent valid and infringed and was \"final except for the ordering of an accounting.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"McLish v. Roff","cite":"141 U.S. 661","y":1891,"id":"scdb/1891-036","sc":1,"sum":"Under section 5 of the Act of March 3, 1891, c. 517, 26 Stat..826, “ to establish Circuit Courts of Appeal,” etc., the appeal or writ of error which may be taken “ from the existing Circuit Courts direct to the Supreme Court,” “ in any case in which the jurisdiction of the court is in issue,’-’ can be taken only after final judgment; when the party against whom.it is rendered must elect whether he will take his writ …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27","1":"18"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"137 S. Ct. 1702","y":2017,"id":"2016/15-457","sc":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"0":"27-29"}},{"t":"case","label":"Midland Asphalt Corp. v. United States","cite":"489 U.S. 794","y":1989,"id":"1988/87-1905","sc":1,"sum":"A district court order denying a defendant's motion to dismiss an indictment for an alleged violation of Rule 6(e) is not immediately appealable under § 1291. Since petitioners have not yet been sentenced, the District Court's order is not a final judgment ending the litigation on the merits. Moreover, whatever view is taken of the scope of Mechanik (an issue not resolved here), an order such as that at issue does …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"ar":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39, 41","1":"2, 34","3":"9"}},{"t":"case","label":"Mohamed v. Uber Techs., Inc.","cite":"848 F.3d 1201","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/1201/","by":{"0":"48"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"op":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Morgan v. Sundance, Inc.","cite":"142 S. Ct. 1708","y":2022,"id":"2021/21-328","sc":1,"ar":1,"sum":"Federal courts may not adopt an arbitration-specific rule conditioning a waiver of the right to arbitrate on a showing of prejudice.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","1":"8, 15, 36, 43","2":"14, 17, 25, 27, 28, 30-33, 35","3":"9, 13, 14, 21"}},{"t":"case","label":"Moses H. Cone Mem’l Hosp. v. Mercury Constr. Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"op":3,"ar":2,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 6, 18, 19, 33, 43-45","1":"2, 7, 30-33, 42","2":"19, 43","3":"12, 23"}},{"t":"case","label":"Nationwide Biweekly Admin., Inc. v. Owen","cite":"873 F.3d 716","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/873/716/","by":{"0":"46"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"op":6,"ar":11,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"46","1":"1, 4, 6, 8, 10, 13, 39, 42"}},{"t":"case","label":"North Star Steel Co. v. Thomas","cite":"515 U.S. 29","y":1995,"id":"1994/94-834","sc":1,"op":1,"sum":"The Court held that State law is the proper source of the limitations period for civil actions brought to enforce WARN. Where a federal statute fails to provide any limitations period for a new cause of action, the Court noted that its longstanding practice has been to borrow the limitations period from the most closely analogous state statute.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Preston v. Ferrer","cite":"552 U.S. 346","y":2008,"id":"2007/06-1463","sc":1,"sum":"The Court disagreed with the California Labor Commissioner's assessment and allowed the arbitration to continue. Justice Ruth Bader Ginsburg, writing for an 8-1 majority, stated that the California law granting exclusive jurisdiction to the Labor Commission was superseded by the Federal Arbitration Act because the parties to this case had agreed to arbitrate any contractual disputes.","sumSrc":"Oyez","by":{"0":"49","1":"30"}},{"t":"case","label":"Puerto Rico Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"op":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Renegotiation Bd. v. Bannercraft Clothing Co.","cite":"415 U.S. 1","y":1974,"id":"1973/72-822","sc":1,"sum":"Respondents, whose profits on defense contracts are undergoing renegotiation pursuant to the Renegotiation Act of 1951, sued in the District Court under the Freedom of Information Act (FOIA) to enjoin petitioner Board from withholding documents that respondents had requested and from conducting any further renegotiation proceedings until the documents were produced. The District Court in each case granted injunctive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","3":"19"}},{"t":"case","label":"Rent-A-Center, W., Inc. v. Jackson","cite":"561 U.S. 63","y":2010,"id":"2009/09-497","sc":1,"sum":"The Court held that district courts are required in all cases to determine whether an arbitration agreement, subject to the Federal Arbitration Act, is unconscionable.","sumSrc":"Oyez","by":{"0":"8, 32","2":"19, 20, 32, 43"}},{"t":"case","label":"Reyna v. Int’l Bank of Com.","cite":"839 F.3d 373","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/373/","by":{"0":"48"}},{"t":"case","label":"Rivera-Torres v. Ortiz Velez","cite":"341 F.3d 86","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/341/86/","by":{"0":"51, 52"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Stateside Mach. Co. v. Alperin","cite":"526 F.2d 480","y":1975,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/526/480/","by":{"0":"32"}},{"t":"case","label":"Stewart v. Donges","cite":"915 F.2d 572","y":1990,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/915/572/","op":1,"by":{"0":"51","1":"35"}},{"t":"case","label":"Stiner v. Brookdale Senior Living, Inc.","cite":"810 F. App’x 531","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/810/531/","by":{"0":"47, 48"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds Int’l Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"8","3":"11"}},{"t":"case","label":"Stromberg v. Qualcomm Inc.","cite":"14 F.4th 1059","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/14/1059/","by":{"0":"48"}},{"t":"case","label":"Suski v. Coinbase, Inc.","cite":"55 F.4th 1227","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/1227/","op":1,"ar":2,"by":{"0":"13, 14","1":"40"}},{"t":"case","label":"United States v. DeFries","cite":"129 F.3d 1293","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/129/1293/","by":{"0":"21"}},{"t":"case","label":"United States v. Dunbar","cite":"611 F.2d 985","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/611/985/","op":1,"by":{"0":"40"}},{"t":"case","label":"United States v. Grabinski","cite":"674 F.2d 677","y":1982,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/674/677/","op":1,"by":{"0":"51"}},{"t":"case","label":"United States v. Head","cite":"697 F.2d 1200","y":1982,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/697/1200/","by":{"0":"51"}},{"t":"case","label":"United States v. Hines","cite":"689 F.2d 934","y":1982,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/689/934/","by":{"0":"40"}},{"t":"case","label":"United States v. Leppo","cite":"634 F.2d 101","y":1980,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.2d/634/101/","by":{"0":"51"}},{"t":"case","label":"United States v. MacDonald","cite":"435 U.S. 850","y":1978,"id":"1977/75-1892","sc":1,"sum":"A defendant may not, before trial, appeal a federal district court's order denying his motion to dismiss an indictment because of an alleged violation of his Sixth Amendment right to a speedy trial. Pp. 853-863. 531 F. 2d 196, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"United States v. Powell","cite":"24 F.3d 28","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/24/28/","by":{"0":"41"}},{"t":"case","label":"Viking River Cruises, Inc. v. Moriana","cite":"142 S. Ct. 1906","y":2022,"id":"2021/20-1573","sc":1,"op":1,"sum":"The Federal Arbitration Act preempts a rule of California law that invalidates contractual waivers of the right to assert representative claims under “PAGA”—California’s Labor Code Private Attorneys General Act of 2004—insofar as that rule precludes division of PAGA actions into individual and non-individual claims through an agreement to arbitrate.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5, 33","1":"3, 7, 28, 30, 42","3":"10"}},{"t":"case","label":"Weingarten Realty Invs. v. Miller","cite":"661 F.3d 904","y":2011,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/661/904/","op":2,"by":{"0":"41","1":"44"}},{"t":"case","label":"Wolfe v. Clarke","cite":"718 F.3d 277","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/718/277/","by":{"0":"21"}},{"t":"case","label":"Wooten v. Roach","cite":"964 F.3d 395","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/964/395/","by":{"0":"40"}},{"t":"case","label":"Yates v. City of Cleveland","cite":"941 F.2d 444","y":1991,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/941/444/","op":1,"by":{"0":"51"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"0":"5","2":"17, 18, 43, 44"}},{"t":"usc","label":"9 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/9/2","stext":{"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","paras":[[0,"A written provision in any maritime transaction or a contract evidencing a transaction involving commerce to settle by arbitration a controversy thereafter arising out of such contract or transaction, or the refusal to perform the whole or any part thereof, or an agreement in writing to submit to arbitration an existing controversy arising out of such a contract, transaction, or refusal, shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract or as otherwise provided in chapter 4."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/2?type=usc&year=mostrecent&link-type=html"},"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","tname":"Arbitration","by":{"0":"6","2":"7, 17, 18, 44, 45, 46, 47, 48, 49, 50, 51"}},{"t":"usc","label":"9 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/9/3","stext":{"head":"§3. Stay of proceedings where issue therein referable to arbitration","paras":[[0,"If any suit or proceeding be brought in any of the courts of the United States upon any issue referable to arbitration under an agreement in writing for such arbitration, the court in which such suit is pending, upon being satisfied that the issue involved in such suit or proceeding is referable to arbitration under such an agreement, shall on application of one of the parties stay the trial of the action until such arbitration has been had in accordance with the terms of the agreement, providing the applicant for the stay is not in default in proceeding with such arbitration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/3?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":6,"head":"§3. Stay of proceedings where issue therein referable to arbitration","tname":"Arbitration","by":{"0":"6, 7, 30","1":"10-12","2":"39, 41, 43, 44-45, 47, 50-51","3":"12, 13"}},{"t":"usc","label":"9 U.S.C. § 4","url":"https://www.law.cornell.edu/uscode/text/9/4","stext":{"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","paras":[[0,"A party aggrieved by the alleged failure, neglect, or refusal of another to arbitrate under a written agreement for arbitration may petition any United States district court which, save for such agreement, would have jurisdiction under title 28, in a civil action or in admiralty of the subject matter of a suit arising out of the controversy between the parties, for an order directing that such arbitration proceed in the manner provided for in such agreement. Five days' notice in writing of such application shall be served upon the party in default. Service thereof shall be made in the manner provided by the Federal Rules of Civil Procedure. The court shall hear the parties, and upon being satisfied that the making of the agreement for arbitration or the failure to comply therewith is not in issue, the court shall make an order directing the parties to proceed to arbitration in accordance with the terms of the agreement. The hearing and proceedings, under such agreement, shall be within the district in which the petition for an order directing such arbitration is filed. If the making of the arbitration agreement or the failure, neglect, or refusal to perform the same be in issue, the court shall proceed summarily to the trial thereof. If no jury trial be demanded by the party alleged to be in default, or if the matter in dispute is within admiralty jurisdiction, the court shall hear and determine such issue. Where such an issue is raised, the party alleged to be in default may, except in cases of admiralty, on or before the return day of the notice of application, demand a jury trial of such issue, and upon such demand the court shall make an order referring the issue or issues to a jury in the manner provided by the Federal Rules of Civil Procedure, or may specially call a jury for that purpose. If the jury find that no agreement in writing for arbitration was made or that there is no default in proceeding thereunder, the proceeding shall be dismissed. If the jury find that an agreement for arbitration was made in writing and that there is a default in proceeding thereunder, the court shall make an order summarily directing the parties to proceed with the arbitration in accordance with the terms thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/4?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","tname":"Arbitration","by":{"0":"6, 7","2":"44, 45, 51"}},{"t":"usc","label":"9 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/9/16","subs":["(a)","(a)(1)(C)","(b)"],"stext":{"head":"§16. Appeals","paras":[[0,"(a) An appeal may be taken from—"],[1,"(1) an order—"],[2,"(A) refusing a stay of any action under section 3 of this title,"],[2,"(B) denying a petition under section 4 of this title to order arbitration to proceed,"],[2,"(C) denying an application under section 206 of this title to compel arbitration,"],[2,"(D) confirming or denying confirmation of an award or partial award, or"],[2,"(E) modifying, correcting, or vacating an award;"],[1,"(2) an interlocutory order granting, continuing, or modifying an injunction against an arbitration that is subject to this title; or"],[1,"(3) a final decision with respect to an arbitration that is subject to this title."],[0,"(b) Except as otherwise provided in section 1292(b) of title 28, an appeal may not be taken from an interlocutory order—"],[1,"(1) granting a stay of any action under section 3 of this title;"],[1,"(2) directing arbitration to proceed under section 4 of this title;"],[1,"(3) compelling arbitration under section 206 of this title; or"],[1,"(4) refusing to enjoin an arbitration that is subject to this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/16?type=usc&year=mostrecent&link-type=html"},"op":28,"ar":6,"head":"§16. Appeals","tname":"Arbitration","by":{"0":"7, 30, 31, 43, 1-5, 7, 16-20, 24-31, 36, 38, 40-43, 45, 46, 50, 20, 26, 3, 5, 7, 16, 29","1":"1-13, 15-16, 22, 25, 28, 31, 33, 35-36, 39, 40, 44-48, 9, 11","2":"1-3, 12-26, 32, 34-35, 38-40, 44, 51-52, 1, 22, 26, 31, 35, 44","3":"3-6, 8, 11, 13-19, 1-4, 6, 11-13, 21, 22, 2"}},{"t":"usc","label":"9 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/9/206","stext":{"head":"§206. Order to compel arbitration; appointment of arbitrators","paras":[[0,"A court having jurisdiction under this chapter may direct that arbitration be held in accordance with the agreement at any place therein provided for, whether that place is within or without the United States. Such court may also appoint arbitrators in accordance with the provisions of the agreement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§206. Order to compel arbitration; appointment of arbitrators","tname":"Arbitration","by":{"0":"6, 7"}},{"t":"usc","label":"26 U.S.C. § 7482","url":"https://www.law.cornell.edu/uscode/text/26/7482","subs":["(a)(2)","(a)(2)(A)"],"stext":{"head":"§7482. Courts of review","paras":[[0,"(a) Jurisdiction"],[0,"(1) In general"],[1,"The United States Courts of Appeals (other than the United States Court of Appeals for the Federal Circuit) shall have exclusive jurisdiction to review the decisions of the Tax Court, except as provided in section 1254 of Title 28 of the United States Code, in the same manner and to the same extent as decisions of the district courts in civil actions tried without a jury; and the judgment of any such court shall be final, except that it shall be subject to review by the Supreme Court of the United States upon certiorari, in the manner provided in section 1254 of Title 28 of the United States Code."],[0,"(2) Interlocutory orders"],[0,"(A) In general"],[2,"When any judge of the Tax Court includes in an interlocutory order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals may, in its discretion, permit an appeal to be taken from such order, if application is made to it within 10 days after the entry of such order. Neither the application for nor the granting of an appeal under this paragraph shall stay proceedings in the Tax Court, unless a stay is ordered by a judge of the Tax Court or by the United States Court of Appeals which has jurisdiction of the appeal or a judge of that court."],[0,"(B) Order treated as Tax Court decision"],[2,"For purposes of subsections (b) and (c), an order described in this paragraph shall be treated as a decision of the Tax Court."],[0,"(C) Venue for review of subsequent proceedings"],[2,"If a United States Court of Appeals permits an appeal to be taken from an order described in subparagraph (A), except as provided in subsection (b)(2), any subsequent review of the decision of the Tax Court in the proceeding shall be made by such Court of Appeals."],[0,"(3) Certain orders entered under section 6213(a)"],[1,"An order of the Tax Court which is entered under authority of section 6213(a) and which resolves a proceeding to restrain assessment or collection shall be treated as a decision of the Tax Court for purposes of this section and shall be subject to the same review by the United States Court of Appeals as a similar order of a district court."],[0,"(b) Venue"],[0,"(1) In general"],[1,"Except as otherwise provided in paragraphs (2) and (3), such decisions may be reviewed by the United States court of appeals for the circuit in which is located—"],[2,"(A) in the case of a petitioner seeking redetermination of tax liability other than a corporation, the legal residence of the petitioner,"],[2,"(B) in the case of a corporation seeking redetermination of tax liability, the principal place of business or principal office or agency of the corporation, or, if it has no principal place of business or principal office or agency in any judicial circuit, then the office to which was made the return of the tax in respect of which the liability arises,"],[2,"(C) in the case of a person seeking a declaratory decision under section 7476, the principal place of business, or principal office or agency of the employer,"],[2,"(D) in the case of an organization seeking a declaratory decision under section 7428, the principal office or agency of the organization,"],[2,"(E) in the case of a petition under section 6234, the principal place of business of the partnership,"],[2,"(F) in the case of a petition under section 6015(e), the legal residence of the petitioner, or"],[2,"(G) in the case of a petition under section 6320 or 6330—"],[3,"(i) the legal residence of the petitioner if the petitioner is an individual, and"],[3,"(ii) the principal place of business or principal office or agency if the petitioner is an entity other than an individual."],[1,"If for any reason no subparagraph of the preceding sentence applies, then such decisions may be reviewed by the Court of Appeals for the District of Columbia. For purposes of this paragraph, the legal residence, principal place of business, or principal office or agency referred to herein shall be determined as of the time the petition seeking redetermination of tax liability was filed with the Tax Court or as of the time the petition seeking a declaratory decision under section 7428 or 7476, or the petition under section 6234, was filed with the Tax Court."],[0,"(2) By agreement"],[1,"Notwithstanding the provisions of paragraph (1), such decisions may be reviewed by any United States Court of Appeals which may be designated by the Secretary and the taxpayer by stipulation in writing."],[0,"(3) Declaratory judgment actions relating to status of certain governmental obligations"],[1,"In the case of any decision of the Tax Court in a proceeding under section 7478, such decision may only be reviewed by the Court of Appeals for the District of Columbia."],[0,"(c) Powers"],[0,"(1) To affirm, modify, or reverse"],[1,"Upon such review, such courts shall have power to affirm or, if the decision of the Tax Court is not in accordance with law, to modify or to reverse the decision of the Tax Court, with or without remanding the case for a rehearing, as justice may require."],[0,"(2) To make rules"],[1,"Rules for review of decisions of the Tax Court shall be those prescribed by the Supreme Court under section 2072 of title 28 of the United States Code."],[0,"(3) To require additional security"],[1,"Nothing in section 7483 shall be construed as relieving the petitioner from making or filing such undertakings as the court may require as a condition of or in connection with the review."],[0,"(4) To impose penalties"],[1,"The United States Court of Appeals and the Supreme Court shall have the power to require the taxpayer to pay to the United States a penalty in any case where the decision of the Tax Court is affirmed and it appears that the appeal was instituted or maintained primarily for delay or that the taxpayer's position in the appeal is frivolous or groundless."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7482?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7482. Courts of review","tname":"Internal Revenue Code","by":{"0":"28, 36"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","subs":["(a)(3)","(d)(2)(D)"],"stext":{"head":"§158. Appeals","paras":[[0,"(a) The district courts of the United States shall have jurisdiction to hear appeals 1"],[1,"(1) from final judgments, orders, and decrees;"],[1,"(2) from interlocutory orders and decrees issued under section 1121(d) of title 11 increasing or reducing the time periods referred to in section 1121 of such title; and"],[1,"(3) with leave of the court, from other interlocutory orders and decrees;"],[0,"of bankruptcy judges entered in cases and proceedings referred to the bankruptcy judges under section 157 of this title. An appeal under this subsection shall be taken only to the district court for the judicial district in which the bankruptcy judge is serving."],[0,"(b)(1) The judicial council of a circuit shall establish a bankruptcy appellate panel service composed of bankruptcy judges of the districts in the circuit who are appointed by the judicial council in accordance with paragraph (3), to hear and determine, with the consent of all the parties, appeals under subsection (a) unless the judicial council finds that—"],[1,"(A) there are insufficient judicial resources available in the circuit; or"],[1,"(B) establishment of such service would result in undue delay or increased cost to parties in cases under title 11."],[0,"Not later than 90 days after making the finding, the judicial council shall submit to the Judicial Conference of the United States a report containing the factual basis of such finding."],[0,"(2)(A) A judicial council may reconsider, at any time, the finding described in paragraph (1)."],[0,"(B) On the request of a majority of the district judges in a circuit for which a bankruptcy appellate panel service is established under paragraph (1), made after the expiration of the 1-year period beginning on the date such service is established, the judicial council of the circuit shall determine whether a circumstance specified in subparagraph (A) or (B) of such paragraph exists."],[0,"(C) On its own motion, after the expiration of the 3-year period beginning on the date a bankruptcy appellate panel service is established under paragraph (1), the judicial council of the circuit may determine whether a circumstance specified in subparagraph (A) or (B) of such paragraph exists."],[0,"(D) If the judicial council finds that either of such circumstances exists, the judicial council may provide for the completion of the appeals then pending before such service and the orderly termination of such service."],[0,"(3) Bankruptcy judges appointed under paragraph (1) shall be appointed and may be reappointed under such paragraph."],[0,"(4) If authorized by the Judicial Conference of the United States, the judicial councils of 2 or more circuits may establish a joint bankruptcy appellate panel comprised of bankruptcy judges from the districts within the circuits for which such panel is established, to hear and determine, upon the consent of all the parties, appeals under subsection (a) of this section."],[0,"(5) An appeal to be heard under this subsection shall be heard by a panel of 3 members of the bankruptcy appellate panel service, except that a member of such service may not hear an appeal originating in the district for which such member is appointed or designated under section 152 of this title."],[0,"(6) Appeals may not be heard under this subsection by a panel of the bankruptcy appellate panel service unless the district judges for the district in which the appeals occur, by majority vote, have authorized such service to hear and determine appeals originating in such district."],[0,"(c)(1) Subject to subsections (b) and (d)(2), each appeal under subsection (a) shall be heard by a 3-judge panel of the bankruptcy appellate panel service established under subsection (b)(1) unless—"],[1,"(A) the appellant elects at the time of filing the appeal; or"],[1,"(B) any other party elects, not later than 30 days after service of notice of the appeal;"],[0,"to have such appeal heard by the district court."],[0,"(2) An appeal under subsections (a) and (b) of this section shall be taken in the same manner as appeals in civil proceedings generally are taken to the courts of appeals from the district courts and in the time provided by Rule 8002 of the Bankruptcy Rules."],[0,"(d)(1) The courts of appeals shall have jurisdiction of appeals from all final decisions, judgments, orders, and decrees entered under subsections (a) and (b) of this section."],[0,"(2)(A) The appropriate court of appeals shall have jurisdiction of appeals described in the first sentence of subsection (a) if the bankruptcy court, the district court, or the bankruptcy appellate panel involved, acting on its own motion or on the request of a party to the judgment, order, or decree described in such first sentence, or all the appellants and appellees (if any) acting jointly, certify that—"],[1,"(i) the judgment, order, or decree involves a question of law as to which there is no controlling decision of the court of appeals for the circuit or of the Supreme Court of the United States, or involves a matter of public importance;"],[1,"(ii) the judgment, order, or decree involves a question of law requiring resolution of conflicting decisions; or"],[1,"(iii) an immediate appeal from the judgment, order, or decree may materially advance the progress of the case or proceeding in which the appeal is taken;"],[0,"and if the court of appeals authorizes the direct appeal of the judgment, order, or decree."],[0,"(B) If the bankruptcy court, the district court, or the bankruptcy appellate panel—"],[1,"(i) on its own motion or on the request of a party, determines that a circumstance specified in clause (i), (ii), or (iii) of subparagraph (A) exists; or"],[1,"(ii) receives a request made by a majority of the appellants and a majority of appellees (if any) to make the certification described in subparagraph (A);"],[0,"then the bankruptcy court, the district court, or the bankruptcy appellate panel shall make the certification described in subparagraph (A)."],[0,"(C) The parties may supplement the certification with a short statement of the basis for the certification."],[0,"(D) An appeal under this paragraph does not stay any proceeding of the bankruptcy court, the district court, or the bankruptcy appellate panel from which the appeal is taken, unless the respective bankruptcy court, district court, or bankruptcy appellate panel, or the court of appeals in which the appeal is pending, issues a stay of such proceeding pending the appeal."],[0,"(E) Any request under subparagraph (B) for certification shall be made not later than 60 days after the entry of the judgment, order, or decree."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/158?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§158. Appeals","tname":"Judiciary and Judicial Procedure","by":{"0":"28, 37"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"0":"27"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(b)","(c)","(d)(3)","(e)","(d)","(d)(4)","(d)(4)(B)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"0":"35, 36, 34, 35, 35, 28, 36, 35, 36, 36, 37","1":"12-13, 18, 21, 6, 25-26","2":"31, 32, 1, 2, 14, 23, 24","3":"17, 15, 14, 15, 4, 14, 15"}},{"t":"usc","label":"38 U.S.C. § 7292","url":"https://www.law.cornell.edu/uscode/text/38/7292","subs":["(b)(1)"],"stext":{"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","paras":[[0,"(a) After a decision of the United States Court of Appeals for Veterans Claims is entered in a case, any party to the case may obtain a review of the decision with respect to the validity of a decision of the Court on a rule of law or of any statute or regulation (other than a refusal to review the schedule of ratings for disabilities adopted under section 1155 of this title) or any interpretation thereof (other than a determination as to a factual matter) that was relied on by the Court in making the decision. Such a review shall be obtained by filing a notice of appeal with the Court of Appeals for Veterans Claims within the time and in the manner prescribed for appeal to United States courts of appeals from United States district courts."],[0,"(b)(1) When a judge or panel of the Court of Appeals for Veterans Claims, in making an order not otherwise appealable under this section, determines that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that there is in fact a disagreement between the appellant and the Secretary with respect to that question of law and that the ultimate termination of the case may be materially advanced by the immediate consideration of that question, the judge or panel shall notify the chief judge of that determination. Upon receiving such a notification, the chief judge shall certify that such a question is presented, and any party to the case may then petition the Court of Appeals for the Federal Circuit to decide the question. That court may permit an interlocutory appeal to be taken on that question if such a petition is filed with it within 10 days after the certification by the chief judge of the Court of Appeals for Veterans Claims. Neither the application for, nor the granting of, an appeal under this paragraph shall stay proceedings in the Court of Appeals for Veterans Claims, unless a stay is ordered by a judge of the Court of Appeals for Veterans Claims or by the Court of Appeals for the Federal Circuit."],[0,"(2) For purposes of subsections (d) and (e) of this section, an order described in this paragraph shall be treated as a decision of the Court of Appeals for Veterans Claims."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction to review and decide any challenge to the validity of any statute or regulation or any interpretation thereof brought under this section, and to interpret constitutional and statutory provisions, to the extent presented and necessary to a decision. The judgment of such court shall be final subject to review by the Supreme Court upon certiorari, in the manner provided in section 1254 of title 28."],[0,"(d)(1) The Court of Appeals for the Federal Circuit shall decide all relevant questions of law, including interpreting constitutional and statutory provisions. The court shall hold unlawful and set aside any regulation or any interpretation thereof (other than a determination as to a factual matter) that was relied upon in the decision of the Court of Appeals for Veterans Claims that the Court of Appeals for the Federal Circuit finds to be—"],[1,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[1,"(B) contrary to constitutional right, power, privilege, or immunity;"],[1,"(C) in excess of statutory jurisdiction, authority, or limitations, or in violation of a statutory right; or"],[1,"(D) without observance of procedure required by law."],[0,"(2) Except to the extent that an appeal under this chapter presents a constitutional issue, the Court of Appeals may not review (A) a challenge to a factual determination, or (B) a challenge to a law or regulation as applied to the facts of a particular case."],[0,"(e)(1) Upon such review, the Court of Appeals for the Federal Circuit shall have power to affirm or, if the decision of the Court of Appeals for Veterans Claims is not in accordance with law, to modify or reverse the decision of the Court of Appeals for Veterans Claims or to remand the matter, as appropriate."],[0,"(2) Rules for review of decisions of the Court of Appeals for Veterans Claims shall be those prescribed by the Supreme Court under section 2072 of title 28."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/7292?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7292. Review by United States Court of Appeals for the Federal Circuit","tname":"Veterans' Benefits","by":{"0":"28, 36"}},{"t":"usc","label":"48 U.S.C. § 2166","url":"https://www.law.cornell.edu/uscode/text/48/2166","subs":["(e)(6)"],"stext":{"head":"§2166. Jurisdiction","paras":[[0,"(a) Federal subject matter jurisdiction"],[0,"The district courts shall have—"],[1,"(1) except as provided in paragraph (2), original and exclusive jurisdiction of all cases under this subchapter; and"],[1,"(2) except as provided in subsection (b), and notwithstanding any Act of Congress that confers exclusive jurisdiction on a court or courts other than the district courts, original but not exclusive jurisdiction of all civil proceedings arising under this subchapter, or arising in or related to cases under this subchapter."],[0,"(b) Property jurisdiction"],[0,"The district court in which a case under this subchapter is commenced or is pending shall have exclusive jurisdiction of all property, wherever located, of the debtor as of the commencement of the case."],[0,"(c) Personal jurisdiction"],[0,"The district court in which a case under this subchapter is pending shall have personal jurisdiction over any person or entity."],[0,"(d) Removal, remand, and transfer"],[0,"(1) Removal"],[1,"A party may remove any claim or cause of action in a civil action, other than a proceeding before the United States Tax Court or a civil action by a governmental unit to enforce the police or regulatory power of the governmental unit, to the district court for the district in which the civil action is pending, if the district court has jurisdiction of the claim or cause of action under this section."],[0,"(2) Remand"],[1,"The district court to which the claim or cause of action is removed under paragraph (1) may remand the claim or cause of action on any equitable ground. An order entered under this subsection remanding a claim or cause of action, or a decision not to remand, is not reviewable by appeal or otherwise by the court of appeals under section 158(d), 1291 or 1292 of title 28 or by the Supreme Court of the United States under section 1254 of title 28."],[0,"(3) Transfer"],[1,"A district court shall transfer any civil proceeding arising under this subchapter, or arising in or related to a case under this subchapter, to the district court in which the case under this subchapter is pending."],[0,"(e) Appeal"],[0,"(1) An appeal shall be taken in the same manner as appeals in civil proceedings generally are taken to the courts of appeals from the district court."],[0,"(2) The court of appeals for the circuit in which a case under this subchapter has venue pursuant to section 2167 of this title shall have jurisdiction of appeals from all final decisions, judgments, orders and decrees entered under this subchapter by the district court."],[0,"(3) The court of appeals for the circuit in which a case under this subchapter has venue pursuant to section 2167 of this title shall have jurisdiction to hear appeals of interlocutory orders or decrees if—"],[1,"(A) the district court on its own motion or on the request of a party to the order or decree certifies that—"],[2,"(i) the order or decree involves a question of law as to which there is no controlling decision of the court of appeals for the circuit or of the Supreme Court of the United States, or involves a matter of public importance;"],[2,"(ii) the order or decree involves a question of law requiring the resolution of conflicting decisions; or"],[2,"(iii) an immediate appeal from the order or decree may materially advance the progress of the case or proceeding in which the appeal is taken; and"],[1,"(B) the court of appeals authorizes the direct appeal of the order or decree."],[0,"(4) If the district court on its own motion or on the request of a party determines that a circumstance specified in clauses (i), (ii), or (iii) of paragraph (3)(A) exists, then the district court shall make the certification described in paragraph (3)."],[0,"(5) The parties may supplement the certification with a short statement of the basis for the certification issued by the district court under paragraph (3)(A)."],[0,"(6) Except as provided in section 2164(d) of this title, an appeal of an interlocutory order or decree does not stay any proceeding of the district court from which the appeal is taken unless the district court, or the court of appeals in which the appeal is pending, issues a stay of such proceedings pending the appeal."],[0,"(7) Any request for a certification in respect to an interlocutory appeal of an order or decree shall be made not later than 60 days after the entry of the order or decree."],[0,"(f) Reallocation of court staff"],[0,"Notwithstanding any law to the contrary, the clerk of the court in which a case is pending shall reallocate as many staff and assistants as the clerk deems necessary to ensure that the court has adequate resources to provide for proper case management."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/48/2166?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2166. Jurisdiction","tname":"Territories and Insular Possessions","by":{"0":"37"}},{"t":"law","label":"Pub. L. No. 85-919","url":"https://www.govinfo.gov/link/statute/72/1770","by":{"0":"36"}},{"t":"law","label":"Pub. L. No. 102-572","url":"https://www.govinfo.gov/link/statute/106/4506","by":{"0":"37"}},{"t":"law","label":"Veterans’ Judicial Review Act, Pub. L. No. 100-687","url":"https://www.govinfo.gov/link/statute/102/4105","by":{"0":"36"}},{"t":"rule","label":"Fed. R. App. P. 38","url":"https://www.law.cornell.edu/rules/frap/rule_38","by":{"0":"50"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(f)"],"by":{"0":"28, 37"}},{"t":"rule","label":"Fed. R. Civ. P. 42","url":"https://www.law.cornell.edu/rules/frcp/rule_42","subs":["(a)"],"by":{"0":"26"}},{"t":"rule","label":"Fed. R. Civ. P. 62","url":"https://www.law.cornell.edu/rules/frcp/rule_62","subs":["(a)","(c)(1)","(c)(2)"],"by":{"0":"35, 36, 35, 36"}},{"t":"case","label":"Albury v. Daymar Colls. Grp., LLC","cite":"2012 WL 1190894","y":2012,"court":"W.D. Ky. Apr. 6","by":{"1":"33"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"1":"2, 8, 34"}},{"t":"case","label":"Balt. Contractors v. Bodinger","cite":"348 U.S. 176","y":1955,"id":"scdb/1954-020","sc":1,"sum":"In an action for an accounting, a federal district court denied a stay under § 3 of the United States Arbitration Act, pending arbitration. Held.: An appeal to a federal court of appeals could not be taken.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Bd. of Educ. of City of N.Y. v. City-Wide Comm. for Integration of Schs.","cite":"342 F.2d 284","y":1965,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/342/284/","by":{"1":"22"}},{"t":"case","label":"Bernhardt v. Polygraphic Co. of Am.","cite":"350 U.S. 198","y":1956,"id":"1955/49","sc":1,"op":1,"sum":"The judgment of the Court of Appeals is reversed and the cause is remanded to the District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10","2":"18"}},{"t":"case","label":"Black v. Wigington","cite":"811 F.3d 1259","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/811/1259/","by":{"1":"41"}},{"t":"case","label":"Boone v. Lightner","cite":"319 U.S. 561","y":1943,"id":"scdb/1942-138","sc":1,"sum":"Section 201 of the Soldiers' and Sailors' Civil Relief Act of 1940, providing for stays in court proceedings involving persons in military service, addresses to the discretion of the court the question whether \"the ability of... the defendant to conduct his defense is not materially affected by reason of his military service.\" In the circumstances of this case, denial of a stay at the instance of a defendant in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"-iv- Camara v. Mastro’s Restaurants LLC","cite":"2018 WL 11249123","y":2018,"court":"D.D.C. Nov. 26","by":{"1":"44"}},{"t":"case","label":"Columbus-Am. Discovery Grp. v. Atl. Mut. Ins. Co.","cite":"203 F.3d 291","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/203/291/","sum":"Stating “the trial court has authority to pursue its own proceedings filed when a § 1292(a)(3) appeal is pending”.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"CompuCredit Corp. v. Greenwood","cite":"565 U.S. 95","y":2012,"id":"2011/10-948","sc":1,"sum":"The Court held that the Credit Repair Organizations Act does not give credit card users the right to bring a suit against their card companies in court.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Coumou v. United States","cite":"1995 WL 144581","y":1995,"court":"E.D. La. Mar. 30","sum":"Rejecting argument that notice of appeal prevents district courts from -22- proceeding with damages phase of trial; rather, the district court may not proceed with the “bifurcated liability portions” on appeal.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"142 S. Ct. 1562","y":2022,"id":"2021/20-219","sc":1,"sum":"Emotional distress damages are not recoverable in a private action to enforce either the Rehabilitation Act of 1973 or the Affordable Care Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Ellison v. Am. Petroleum Inst.","cite":"2021 WL 3711072","y":2021,"court":"D. Minn. Aug. 20","by":{"1":"44"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"13","3":"10"}},{"t":"case","label":"F.T.C. v. Standard Oil Co. of Cal.","cite":"449 U.S. 232","y":1980,"id":"1980/79-900","sc":1,"op":1,"sum":"The FTC's issuance of its complaint was not \"final agency action\" under § 10 (c) of the APA and hence was not judicially reviewable before the conclusion of the administrative adjudication.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Fed. Republic of Germany v. Philipp","cite":"141 S. Ct. 703","y":2021,"id":"2020/19-351","sc":1,"sum":"The Foreign Sovereign Immunities Act’s expropriation exception, 28 U. S. C. §1605(a)(3), incorporates the domestic takings rule, which recognizes that a foreign sovereign’s taking of its own nationals’ property is not a violation of international law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"42"}},{"t":"case","label":"First Options of Chicago, Inc. v. Kaplan","cite":"514 U.S. 938","y":1995,"id":"1994/94-560","sc":1,"op":2,"ar":4,"sum":"The Court held that the arbitrability of the Kaplan/First Options dispute was subject to independent review by the courts and that, rather than a special abuse of discretion standard, courts of appeals should apply ordinary standards when reviewing district court decisions upholding arbitration awards. \"We conclude that, because the Kaplans did not clearly agree to submit the question of arbitrability to arbitration, the Court of Appeals was correct in finding that the arbitrability of the Kaplan/First Options dispute was subject to independent review by the courts,\" wrote Justice Breyer for the Court.","sumSrc":"Oyez","by":{"1":"13, 16, 35"}},{"t":"case","label":"-v- Gannett Co., Inc. v. Clark Constr. Grp., Inc.","cite":"286 F.3d 737","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/286/737/","by":{"1":"32"}},{"t":"case","label":"Great Am. Boat Co. v. Alsthom Atl., Inc.","cite":"1987 WL 4766","y":1987,"court":"E.D. La. Apr. 8","by":{"1":"22"}},{"t":"case","label":"Guifu Li v. A Perfect Franchise, Inc.","cite":"2011 WL 2293221","y":2011,"court":"N.D. Cal. June 8","sum":"Recognizing that where an agreement “provides the parties adequate opportunity to conduct discovery,” “even if Defendants[’] appeal is successful, it appears that the discovery costs arising during the appeal are inevitable”.","sumSrc":"brief:1","by":{"1":"45"}},{"t":"case","label":"Hagans v. Lavine","cite":"415 U.S. 528","y":1974,"id":"1973/72-6476","sc":1,"sum":"Petitioners, recipients of public assistance under the federal-state Aid to Families with Dependent Children (AFDC) program, brought this action under 42 U. S..C. § 1983 and 28 U.S. C. § 2201 challenging a New York regulation permitting the State to recoup prior unscheduled payments for rent from subsequent grants under the AFDC program, on the ground that the regulation violated the Equal Protection Clause of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs. of Chi.","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Health Commc’ns v. Delphos","cite":"1988 WL 13180","y":1988,"court":"D.D.C. Feb. 11","by":{"1":"22"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17, 38, 47"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"ar":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"9, 14"}},{"t":"case","label":"Hilton v. Braunskill","cite":"481 U.S. 770","y":1987,"id":"1986/86-108","sc":1,"sum":"In deciding under Rules 23(c) and (d) whether to stay pending appeal a district court order granting relief to a habeas petitioner, federal courts are not restricted to considering only the petitioner's risk of flight. The history of federal habeas corpus practice indicates that a court has broad discretion in conditioning a judgment granting habeas relief, and a court's denial of enlargement to a successful habeas …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39","2":"34"}},{"t":"case","label":"-vi- Hinkle v. Phillips 66 Co.","cite":"2021 WL 8055644","y":2021,"court":"W.D. Tex. Dec. 21","by":{"1":"40"}},{"t":"case","label":"Hutchinson v. People of State of N.Y.","cite":"86 S. Ct. 5","y":1965,"url":"https://www.courtlistener.com/c/S.%20Ct./86/5/","sc":1,"by":{"1":"22"}},{"t":"case","label":"Isbrandtsen Co. v. Johnson","cite":"343 U.S. 779","y":1952,"id":"scdb/1951-093","sc":1,"sum":"In an admiralty proceeding by a seaman against his employer to recover wages earned on a merchant vessel of United States registry, the employer may not set off against the seaman's wages its expenditures for the medical care and hospitalization of another member of the crew necessitated by injuries unjustifiably inflicted on him by the seaman during the voyage on which the wages were earned.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Jackson v. Amazon.com, Inc.","cite":"2021 WL 5579205","y":2021,"court":"S.D. Cal. Nov. 30","sum":"Finding likelihood of success on the merits where legal issues were novel.","sumSrc":"brief:1","by":{"1":"40-41"}},{"t":"case","label":"Johnson v. 3M Co.","cite":"55 F.4th 1304","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/1304/","by":{"1":"20"}},{"t":"case","label":"Kaszuk v. Bakery & Confectionery Union & Indus. Int’l Pension Fund","cite":"791 F.2d 548","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/791/548/","by":{"1":"20"}},{"t":"case","label":"LaDuke v. Burlington R.R. Co.","cite":"879 F.2d 1556","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/879/1556/","by":{"1":"32"}},{"t":"case","label":"Landry v. United States","cite":"1994 WL 122184","y":1994,"court":"5th Cir. Mar. 29","by":{"1":"21"}},{"t":"case","label":"Lauro Lines s.r.l. v. Chasser","cite":"490 U.S. 495","y":1989,"id":"1988/88-23","sc":1,"sum":"An interlocutory order denying a defendant's motion to dismiss a damages action on the basis of a contractual forum-selection clause is not immediately appealable under § 1291. Such an order is not final in the usual sense, for it does not end the litigation on the merits but, on the contrary, ensures that the litigation will continue. Nor does the order fall within the narrow exception to the normal application of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 16, 34, 38","3":"11"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"McCauley v. Halliburton Energy Servs., Inc.","cite":"413 F.3d 1158","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/413/1158/","op":1,"sum":"Recognizing that the FAA nowhere provides for stays pending arbitrability appeals.","sumSrc":"brief:2","by":{"1":"38","2":"3, 29, 32, 42"}},{"t":"case","label":"Medtronic Sofamor Danek, Inc. v. Gannon","cite":"2017 WL 5135556","y":2017,"court":"D. Minn. Nov. 3","by":{"1":"32"}},{"t":"case","label":"Merrill v. Milligan","cite":"142 S. Ct. 879","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/879/","sc":1,"by":{"1":"42"}},{"t":"case","label":"Mitsubishi Motors Corp. v. Soler ChryslerPlymouth, Inc.","cite":"473 U.S. 614","y":1985,"id":"1984/83-1569","sc":1,"sum":"The Supreme Court held that claims arising under the Sherman Act and encompassed in a valid arbitration clause in an international commercial transaction are arbitrable under the federal Arbitration Act. Justice John Paul Stevens dissented, arguing that a fair construction of the arbitration clause does not encompass antitrust claims.","sumSrc":"Oyez","by":{"1":"28","3":"10"}},{"t":"case","label":"N.Y. State Nat’l Org. for Women v. Terry","cite":"886 F.2d 1339","y":1989,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/886/1339/","by":{"1":"21"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"10, 15","2":"12"}},{"t":"case","label":"Nowak v. Tak How Invs., Ltd.","cite":"94 F.3d 708","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/94/708/","by":{"1":"32"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"9, 17"}},{"t":"case","label":"Overlook Gardens Props., LLC v. Orix USA, L.P.","cite":"2017 WL 4953905","y":2017,"court":"M.D. Ga. Nov. 1","by":{"1":"33"}},{"t":"case","label":"-viii- Pa. Co. v. Bender","cite":"148 U.S. 255","y":1893,"id":"scdb/1892-145","sc":1,"sum":"Under the act of March 3,1887, 24 Stat. c. 373, § 2, pp. 552, 553, a finding by the Circuit Court of -the United States, onan application for the removal of a cause from a state court, that the application is sufficient, and such as entitles the defendant to remove the cause to a Federal-court, does not, of itself, work such removal, but an order of the court to that effect, equivalent to a-judgment, must be made.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"6, 11","3":"13"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Philipp v. Fed. Republic of Germany","cite":"253 F. Supp. 3d 84","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/253/84/","by":{"1":"33"}},{"t":"case","label":"Richards v. Ernst & Young LLP","cite":"2012 WL 92738","y":2012,"court":"N.D. Cal. Jan. 11","by":{"1":"43"}},{"t":"case","label":"Richardson-Merrell, Inc. v. Koller","cite":"472 U.S. 424","y":1985,"id":"1984/84-127","sc":1,"sum":"Orders disqualifying counsel in a civil case are not collateral orders subject to immediate appeal as \"final judgments\" within the meaning of § 1291, and hence the Court of Appeals lacked jurisdiction to entertain respondent's appeal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 25","2":"37"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/Am. Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"sum":"Upon being notified that she was' going to be discharged on a specific date from her position as aprobationary Government employee, respondent filed this action claiming that the applicable Civil Service regulations for discharge of probationary employees had not been followed, and seeking a temporary injunction against her dismissal pending an administrative appeal to the Civil Service Commission (CSC). The …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Scherk v. Alberto-Culver Co.","cite":"417 U.S. 506","y":1974,"id":"1973/73-781","sc":1,"op":1,"sum":"The arbitration clause is to be respected and enforced by federal courts in accord with the explicit provisions of the United States Arbitration Act that an arbitration agreement, such as is here involved, \"shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract.\" 9 U. S. C. §§ 1, 2. Wilko v. Swan, supra, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30","3":"10"}},{"t":"case","label":"Scripps-Howard Radio v. Fed. Commc’ns Comm’n","cite":"316 U.S. 4","y":1942,"id":"scdb/1941-046","sc":1,"ar":1,"by":{"1":"9, 18"}},{"t":"case","label":"Silberman v. Bogle","cite":"486 F. Supp. 70","y":1980,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./486/70/","by":{"1":"21"}},{"t":"case","label":"-ix- Simon v. Republic of Hungary","cite":"812 F.3d 127","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/812/127/","by":{"1":"42"}},{"t":"case","label":"Stack v. Boyle","cite":"342 U.S. 1","y":1951,"id":"scdb/1951-001","sc":1,"sum":"Bail has not been fixed by proper methods in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Taylor v. Sterrett","cite":"640 F.2d 663","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/640/663/","by":{"1":"20"}},{"t":"case","label":"The Bremen v. Zapata Off-Shore Co.","cite":"407 U.S. 1","y":1972,"id":"1971/71-322","sc":1,"sum":"The forum-selection clause, which was a vital part of the towing contract, is binding on the parties unless respondent can meet the heavy burden of showing that its enforcement would be unreasonable, unfair, or unjust. Pp. 8-20. 428 F. 2d 888 and 446 F. 2d 907, vacated and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Trompeter v. Ally Fin., Inc.","cite":"914 F. Supp. 2d 1067","y":2012,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/914/1067/","by":{"1":"46"}},{"t":"case","label":"United States v. Hitchmon","cite":"587 F.2d 1357","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/587/1357/","by":{"1":"27"}},{"t":"case","label":"United States v. Naftalin","cite":"441 U.S. 768","y":1979,"id":"1978/78-561","sc":1,"sum":"Section 17 (a) (1) prohibits frauds against brokers as well as investors.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Vine v. PLS Fin. Servs., Inc.","cite":"2019 WL 4257108","y":2019,"court":"E.D. Tex. Sept. 9","sum":"Finding low likelihood of success where Fifth Circuit had already addressed and dismissed movant’s arguments.","sumSrc":"brief:1","by":{"1":"41"}},{"t":"case","label":"Ward v. Est. of Goossen","cite":"2014 WL 7273911","y":2014,"court":"N.D. Cal. Dec. 22","by":{"1":"44, 45"}},{"t":"case","label":"-x- Yeomans v. World Fin. Grp. Ins. Agency, Inc.","cite":"2021 WL 1772808","y":2021,"court":"N.D. Cal. Mar. 19","by":{"1":"45"}},{"t":"case","label":"Zaborowski v. MHN Gov’t Servs., Inc.","cite":"2013 WL 1832638","y":2013,"court":"N.D. Cal. May 1","by":{"1":"43, 46","3":"20"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","by":{"1":"29"}},{"t":"usc","label":"15 U.S.C. § 1693","url":"https://www.law.cornell.edu/uscode/text/15/1693","by":{"1":"3"}},{"t":"usc","label":"18 U.S.C. § 2339B","url":"https://www.law.cornell.edu/uscode/text/18/2339B","subs":["(f)","(f)(5)(B)(i)","(f)(5)(B)(ii)","(f)(5)(B)(iii)"],"stext":{"head":"§2339B. Providing material support or resources to designated foreign terrorist organizations","paras":[[0,"(a) Prohibited Activities.—"],[1,"(1) Unlawful conduct.—Whoever knowingly provides material support or resources to a foreign terrorist organization, or attempts or conspires to do so, shall be fined under this title or imprisoned not more than 20 years, or both, and, if the death of any person results, shall be imprisoned for any term of years or for life. To violate this paragraph, a person must have knowledge that the organization is a designated terrorist organization (as defined in subsection (g)(6)), that the organization has engaged or engages in terrorist activity (as defined in section 212(a)(3)(B) of the Immigration and Nationality Act), or that the organization has engaged or engages in terrorism (as defined in section 140(d)(2) of the Foreign Relations Authorization Act, Fiscal Years 1988 and 1989)."],[1,"(2) Financial institutions.—Except as authorized by the Secretary, any financial institution that becomes aware that it has possession of, or control over, any funds in which a foreign terrorist organization, or its agent, has an interest, shall—"],[2,"(A) retain possession of, or maintain control over, such funds; and"],[2,"(B) report to the Secretary the existence of such funds in accordance with regulations issued by the Secretary."],[0,"(b) Civil Penalty.—Any financial institution that knowingly fails to comply with subsection (a)(2) shall be subject to a civil penalty in an amount that is the greater of—"],[1,"(A) $50,000 per violation; or"],[1,"(B) twice the amount of which the financial institution was required under subsection (a)(2) to retain possession or control."],[0,"(c) Injunction.—Whenever it appears to the Secretary or the Attorney General that any person is engaged in, or is about to engage in, any act that constitutes, or would constitute, a violation of this section, the Attorney General may initiate civil action in a district court of the United States to enjoin such violation."],[0,"(d) Extraterritorial Jurisdiction.—"],[1,"(1) In general.—There is jurisdiction over an offense under subsection (a) if—"],[2,"(A) an offender is a national of the United States (as defined in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22))) or an alien lawfully admitted for permanent residence in the United States (as defined in section 101(a)(20) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(20)));"],[2,"(B) an offender is a stateless person whose habitual residence is in the United States;"],[2,"(C) after the conduct required for the offense occurs an offender is brought into or found in the United States, even if the conduct required for the offense occurs outside the United States;"],[2,"(D) the offense occurs in whole or in part within the United States;"],[2,"(E) the offense occurs in or affects interstate or foreign commerce; or"],[2,"(F) an offender aids or abets any person over whom jurisdiction exists under this paragraph in committing an offense under subsection (a) or conspires with any person over whom jurisdiction exists under this paragraph to commit an offense under subsection (a)."],[1,"(2) Extraterritorial jurisdiction.—There is extraterritorial Federal jurisdiction over an offense under this section."],[0,"(e) Investigations.—"],[1,"(1) In general.—The Attorney General shall conduct any investigation of a possible violation of this section, or of any license, order, or regulation issued pursuant to this section."],[1,"(2) Coordination with the department of the treasury.—The Attorney General shall work in coordination with the Secretary in investigations relating to—"],[2,"(A) the compliance or noncompliance by a financial institution with the requirements of subsection (a)(2); and"],[2,"(B) civil penalty proceedings authorized under subsection (b)."],[1,"(3) Referral.—Any evidence of a criminal violation of this section arising in the course of an investigation by the Secretary or any other Federal agency shall be referred immediately to the Attorney General for further investigation. The Attorney General shall timely notify the Secretary of any action taken on referrals from the Secretary, and may refer investigations to the Secretary for remedial licensing or civil penalty action."],[0,"(f) Classified Information in Civil Proceedings Brought by the United States.—"],[1,"(1) Discovery of classified information by defendants.—"],[2,"(A) Request by united states.—In any civil proceeding under this section, upon request made ex parte and in writing by the United States, a court, upon a sufficient showing, may authorize the United States to—"],[3,"(i) redact specified items of classified information from documents to be introduced into evidence or made available to the defendant through discovery under the Federal Rules of Civil Procedure;"],[3,"(ii) substitute a summary of the information for such classified documents; or"],[3,"(iii) substitute a statement admitting relevant facts that the classified information would tend to prove."],[2,"(B) Order granting request.—If the court enters an order granting a request under this paragraph, the entire text of the documents to which the request relates shall be sealed and preserved in the records of the court to be made available to the appellate court in the event of an appeal."],[2,"(C) Denial of request.—If the court enters an order denying a request of the United States under this paragraph, the United States may take an immediate, interlocutory appeal in accordance with paragraph (5). For purposes of such an appeal, the entire text of the documents to which the request relates, together with any transcripts of arguments made ex parte to the court in connection therewith, shall be maintained under seal and delivered to the appellate court."],[1,"(2) Introduction of classified information; precautions by court.—"],[2,"(A) Exhibits.—To prevent unnecessary or inadvertent disclosure of classified information in a civil proceeding brought by the United States under this section, the United States may petition the court ex parte to admit, in lieu of classified writings, recordings, or photographs, one or more of the following:"],[3,"(i) Copies of items from which classified information has been redacted."],[3,"(ii) Stipulations admitting relevant facts that specific classified information would tend to prove."],[3,"(iii) A declassified summary of the specific classified information."],[2,"(B) Determination by court.—The court shall grant a request under this paragraph if the court finds that the redacted item, stipulation, or summary is sufficient to allow the defendant to prepare a defense."],[1,"(3) Taking of trial testimony.—"],[2,"(A) Objection.—During the examination of a witness in any civil proceeding brought by the United States under this subsection, the United States may object to any question or line of inquiry that may require the witness to disclose classified information not previously found to be admissible."],[2,"(B) Action by court.—In determining whether a response is admissible, the court shall take precautions to guard against the compromise of any classified information, including—"],[3,"(i) permitting the United States to provide the court, ex parte, with a proffer of the witness's response to the question or line of inquiry; and"],[3,"(ii) requiring the defendant to provide the court with a proffer of the nature of the information that the defendant seeks to elicit."],[2,"(C) Obligation of defendant.—In any civil proceeding under this section, it shall be the defendant's obligation to establish the relevance and materiality of any classified information sought to be introduced."],[1,"(4) Appeal.—If the court enters an order denying a request of the United States under this subsection, the United States may take an immediate interlocutory appeal in accordance with paragraph (5)."],[1,"(5) Interlocutory appeal.—"],[2,"(A) Subject of appeal.—An interlocutory appeal by the United States shall lie to a court of appeals from a decision or order of a district court—"],[3,"(i) authorizing the disclosure of classified information;"],[3,"(ii) imposing sanctions for nondisclosure of classified information; or"],[3,"(iii) refusing a protective order sought by the United States to prevent the disclosure of classified information."],[2,"(B) Expedited consideration.—"],[3,"(i) In general.—An appeal taken pursuant to this paragraph, either before or during trial, shall be expedited by the court of appeals."],[3,"(ii) Appeals prior to trial.—If an appeal is of an order made prior to trial, an appeal shall be taken not later than 14 days after the decision or order appealed from, and the trial shall not commence until the appeal is resolved."],[3,"(iii) Appeals during trial.—If an appeal is taken during trial, the trial court shall adjourn the trial until the appeal is resolved, and the court of appeals—"],[4,"(I) shall hear argument on such appeal not later than 4 days after the adjournment of the trial, excluding intermediate weekends and holidays;"],[4,"(II) may dispense with written briefs other than the supporting materials previously submitted to the trial court;"],[4,"(III) shall render its decision not later than 4 days after argument on appeal, excluding intermediate weekends and holidays; and"],[4,"(IV) may dispense with the issuance of a written opinion in rendering its decision."],[2,"(C) Effect of ruling.—An interlocutory appeal and decision shall not affect the right of the defendant, in a subsequent appeal from a final judgment, to claim as error reversal by the trial court on remand of a ruling appealed from during trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2339B?type=usc&year=mostrecent&link-type=html"},"head":"§2339B. Providing material support or resources to designated foreign terrorist organizations","tname":"Crimes and Criminal Procedure","by":{"1":"26","3":"16, 16, 15, 16, 15, 16"}},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 1443","url":"https://www.law.cornell.edu/uscode/text/28/1443","by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(d)"],"by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","subs":["(a)"],"stext":{"head":"§1651. Writs","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law."],[0,"(b) An alternative writ or rule nisi may be issued by a justice or judge of a court which has jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1651?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1651. Writs","tname":"Judiciary and Judicial Procedure","by":{"1":"18"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"26"}},{"t":"law","label":"Pub. L. No. 100-702","url":"https://www.govinfo.gov/link/statute/102/4642","by":{"1":"12","2":"22, 23, 24, 25, 1, 2, 20, 22, 23, 24, 1, 2, 23, 24, 25"}},{"t":"reg","label":"12 C.F.R. § 1005.1-20","url":"https://www.ecfr.gov/current/title-12/section-1005.1-20","by":{"1":"3"}},{"t":"reg","label":"8 C.F.R. § 1003.19","url":"https://www.ecfr.gov/current/title-8/section-1003.19","subs":["(f)"],"by":{"1":"26"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"sum":"The Court held that Indian Regulatory Gaming Act does not create such an exemption. The Court reasoned that despite its parenthetical reference, the language outside the parenthetical was unambiguous and the subsection applied only to Internal Revenue Code provisions that concerned the reporting and withholding of taxes.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"2":"26, 36, 41"}},{"t":"case","label":"Cooper v. Aviall","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"2":"39, 49, 50"}},{"t":"case","label":"Digital Realty Trust, Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"2":"22, 24"}},{"t":"case","label":"DIRECTV, Inc. v. Imburgia","cite":"577 U.S. 47","y":2015,"id":"2015/14-462","sc":1,"sum":"The Court determined that the Federal Arbitration Act preempted state law and required the enforcement of a contract’s arbitration agreement.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"EEOC v. Arabian American Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Engine Mfrs. Ass’n v. South Coast Air Quality Mgmt. Dist.","cite":"541 U.S. 246","y":2004,"id":"2003/02-1343","sc":1,"sum":"In an 8-to-1 opinion written by Justice Antonin Scalia, the Court ruled that distinguishing between rules governing the standards to which engines must be made and the standards at which they may be sold was unreasonable.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"FMC Corp. v. Holliday","cite":"498 U.S. 52","y":1990,"id":"1990/89-1048","sc":1,"sum":"Three provisions of ERISA speak to the question of preemption: the preemption clause, the saving clause, and the deemer clause. The preemption clause establishes as an area of exclusive federal concern the subject of every state law that \"relate[s] to\" an employee benefit plan governed by ERISA.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Gozlon-Peretz v. U.S.","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"sum":"Supervised release applies for all drug offenses in the categories specified by ADAA § 1002 that were committed after the ADAA was enacted but before November 1, 1987.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Gross v. FBL Financial Services, Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"2":"18, 20"}},{"t":"case","label":"Grupo Mexicano de Desarrollo, S. A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Helvering v. Credit Alliance Co.","cite":"316 U.S. 107","y":1942,"id":"scdb/1941-130","sc":1,"sum":"1. Under § 27 (f) of the Revenue Act of 1930, a distribution in liquidation of surplus accumulated since February 28, 1913, is to be treated, in computing the dividends-paid credit for the purpose of the tax imposed by § 14 on undistributed net income, as a taxable dividend paid. P. 110. So held although, under § 112 (b) (6), the distribution resulted in no gain or loss to the distributee for tax purposes; and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Iancu v. Brunetti","cite":"139 S. Ct. 2294","y":2019,"id":"2018/18-302","sc":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"Iselin v. U.S.","cite":"270 U.S. 245","y":1926,"id":"scdb/1925-076","sc":1,"sum":"1. Par. 3 of § 800(a) of Revenue Act of 1918, laying taxes on theater and opera tickets sold at newstands, hotels, etc., for more than the “established price” at the ticket office of the theater or opera house, held inapplicable to sale by a stockholder of box tickets, issued as an incident of his investment in an opera house company, which were not sold at the box-office and for which there was no established price.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21, 40, 41"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"2":"18, 19"}},{"t":"case","label":"Lamps Plus, Inc. v. Varela","cite":"139 S. Ct. 1407","y":2019,"id":"2018/17-988","sc":1,"sum":"Under the Federal Arbitration Act, an ambiguous agreement cannot provide the necessary contractual basis for concluding that the parties agreed to submit to class arbitration.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"40, 43, 45"}},{"t":"case","label":"Loughrin v. U.S.","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Prima Paint Corp. v. Flood & Conklin Mfg. Co.","cite":"388 U.S. 395","y":1967,"id":"1966/343","sc":1,"by":{"2":"32, 33"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Santiago-Lugo v. Warden","cite":"785 F.3d 467","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/785/467/","by":{"2":"37"}},{"t":"case","label":"Secretary of State of Md. v. J. H. Munson Co.","cite":"467 U.S. 947","y":1984,"id":"1983/82-766","sc":1,"sum":"A Maryland statute prohibits a charitable organization, in connection with any fundraising activity, from paying expenses of more than 25% of the amount raised, but authorizes a waiver of this limitation where it would effectively prevent the organization from raising contributions. Respondent is a professional fundraiser whose Maryland customers include various chapters of the Fraternal Order of Police, at least …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Stop Reckless Econ. Instability Caused by Democrats v. Fed. Election Comm’n","cite":"814 F.3d 221","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/814/221/","sum":"Explaining that “federal courts must determine whether they have subject-matter jurisdiction over a claim before proceeding to address its merits”.","sumSrc":"brief:2","by":{"2":"37"}},{"t":"case","label":"U.S. v. Morton","cite":"467 U.S. 822","y":1994,"id":"1983/83-916","sc":1,"sum":"The Government cannot be held liable for honoring a writ of garnishment, such as the one in question here, which is \"regular on its face\" and has been issued by a court with subject-matter jurisdiction to issue such orders. Pp. 827-836. UNITED STATES v. MORTON (a) The words \"legal process\" in § 659(f) must be read in light of the immediately following phrase-\"regular on its face.\" That phrase makes it clear that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"usc","label":"9 U.S.C. § 6","url":"https://www.law.cornell.edu/uscode/text/9/6","stext":{"head":"§6. Application heard as motion","paras":[[0,"Any application to the court hereunder shall be made and heard in the manner provided by law for the making and hearing of motions, except as otherwise herein expressly provided."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/6?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§6. Application heard as motion","tname":"Arbitration","by":{"2":"13, 14, 25, 27","3":"13"}},{"t":"rule","label":"Fed. R. App. P. 8","url":"https://www.law.cornell.edu/rules/frap/rule_8","subs":["(a)"],"by":{"2":"3, 12, 14, 28, 35"}},{"t":"rule","label":"Fed. R. Civ. P. 11","url":"https://www.law.cornell.edu/rules/frcp/rule_11","by":{"2":"10"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"2":"11, 12, 38"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","by":{"2":"27, 28, 29"}},{"t":"rule","label":"Fed. R. Civ. P. 59","url":"https://www.law.cornell.edu/rules/frcp/rule_59","by":{"2":"28, 29"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)"],"by":{"2":"27"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"op":4,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"AT&T Techs., Inc. v. Commc’ns Workers of Am.","cite":"475 U.S. 643","y":1986,"id":"1985/84-1913","sc":1,"sum":"The issue whether, because of express exclusion or other evidence, the dispute over interpretation of Article 20 was subject to the arbitration clause, should have been decided by the District Court and reviewed by the Court of Appeals, and should not have been referred to the arbitrator.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Eberle v. Smith","cite":"2008 WL 238450","y":2008,"court":"S.D. Cal. Jan. 29","by":{"3":"21"}},{"t":"case","label":"Goshtasby v. Bd. of Trs. of Univ. of Illinois","cite":"123 F.3d 427","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/123/427/","by":{"3":"8, 10"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Hegarty v. Somerset County","cite":"25 F.3d 17","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/25/17/","by":{"3":"8"}},{"t":"case","label":"Hovey v. McDonald","cite":"109 U.S. 150","y":1883,"id":"scdb/1883-025","sc":1,"op":1,"ar":2,"sum":"- Amendment — Appeal—District of Columbia — Equity—Execution—Injunction —Practice—Receiver—Supersedeas.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Kasten v. Saint-Gobain Performance Plastics Corp.","cite":"563 U.S. 1","y":2011,"id":"2010/09-834","sc":1,"sum":"The Court held that the Fair Labor Standards Act applies to a complaint, whether oral or written.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"Manrique v. United States","cite":"581 U.S. 116","y":2017,"id":"2016/15-7250","sc":1,"sum":"The Court held that appellate courts do not have jurisdiction over an appeal of a restitution award when the judgment that awarded restitution was entered after the notice of appeal was filed.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"McDonald v. City of West Branch","cite":"466 U.S. 284","y":1984,"id":"1983/83-219","sc":1,"sum":"In a § 1983 action, a federal court should not afford res judicata or collateral estoppel effect to an award in an arbitration proceeding brought pursuant to the terms of a collective-bargaining agreement, and hence petitioner's § 1983 action was not barred by the arbitration award.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Morgan Drexen, Inc. v. Consumer Fin. Prot. Bureau","cite":"785 F.3d 684","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/785/684/","by":{"3":"20"}},{"t":"case","label":"Murphy v. DirecTV, Inc.","cite":"2008 WL 8608808","y":2008,"court":"C.D. Cal. July 1","by":{"3":"21"}},{"t":"case","label":"Republic Steel Corp. v. Maddox","cite":"379 U.S. 650","y":1965,"id":"1964/43","sc":1,"sum":"Under federal policy reflected in the LMRA, contract grievance procedures, which apply to severance as well as other types of claims, must, unless specified as nonexclusive, be exhausted before direct legal redress is sought. Moore v. Illinois Central R. Co., 312 U. S. 630, and Transcontinental& Western Air, Inc. v. Koppal, 345 U. S. 653, distinguished. Pp. 652-659. 275 Ala. 685, 158 So. 2d 492, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10, 11"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"Sherwood v. Marquette Transp. Co.","cite":"587 F.3d 841","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/587/841/","by":{"3":"20"}},{"t":"case","label":"Siegel v. LePore","cite":"234 F.3d 1163","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/234/1163/","by":{"3":"20"}},{"t":"case","label":"Tilton v. SEC","cite":"824 F.3d 276","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/824/276/","by":{"3":"20"}},{"t":"case","label":"United States v. Centracchio","cite":"236 F.3d 812","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/236/812/","by":{"3":"16"}},{"t":"case","label":"United Steelworkers of Am. v. Am. Mfg. Co.","cite":"363 U.S. 564","y":1960,"id":"1959/360","sc":1,"sum":"In a suit under § 301 (a) of the Labor Management Relations Act, 1947, to compel arbitration of a dispute pursuant to a collective bargaining agreement providing for arbitration of all disputes between the parties \"as to the meaning, interpretatiop and application of the provisions of this agreement,\" the function of the court is confined to ascertaining whether the party seeking arbitration is making a claim which …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"usc","label":"18 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/18/3731","by":{"3":"16"}},{"t":"law","label":"Pub. L. No. 97-164","by":{"3":"15"}},{"t":"rule","label":"Fed. R. Civ. P. 26","url":"https://www.law.cornell.edu/rules/frcp/rule_26","subs":["(b)(1)"],"by":{"3":"7"}}]};